#include <iostream>
#include <array>
#include <iomanip>
#include <stdexcept>

int main() {
    constexpr std::size_t responseSize = 10;
    constexpr std::size_t frequencySize = 6; // Indices 0 to 5 (0 is unused)

    const std::array<unsigned int, responseSize> responses = {
        1, 2, 5, 4, 3, 5, 2, 1, 3, 2
    };
    std::array<unsigned int, frequencySize> frequency{}; // Value-initialized to 0

    for (std::size_t answer = 0; answer < responses.size(); ++answer) {
        std::size_t rating = responses[answer];
        try {
            // Safe bounds check using at()
            ++frequency.at(rating);
        } catch (const std::out_of_range& e) {
            std::cout << "Invalid rating encountered: " << rating << "\n";
        }
    }

    std::cout << "Rating" << std::setw(17) << "Frequency" << "\n";
    for (std::size_t rating = 1; rating < frequency.size(); ++rating) {
        std::cout << std::setw(6) << rating
                  << std::setw(17) << frequency[rating] << "\n";
    }

    return 0;
}

#include <iostream>
#include <array>

constexpr std::size_t arraySize = 3;

void staticArrayDemo() {
    // Initialized to 0 on the first call only; persists across calls
    static std::array<int, arraySize> staticArr;

    std::cout << "Static on entry: ";
    for (int val : staticArr) {
        std::cout << val << " ";
    }

    // Modify elements in place using reference in range-based for
    for (int& valRef : staticArr) {
        valRef += 5;
    }

    std::cout << "| on exit: ";
    for (int val : staticArr) {
        std::cout << val << " ";
    }
    std::cout << "\n";
}

void automaticArrayDemo() {
    // Re-initialized every time the function is called
    std::array<int, arraySize> autoArr = {1, 2, 3};

    std::cout << "Auto on entry:   ";
    for (int val : autoArr) {
        std::cout << val << " ";
    }

    for (int& valRef : autoArr) {
        valRef += 5;
    }

    std::cout << "| on exit: ";
    for (int val : autoArr) {
        std::cout << val << " ";
    }
    std::cout << "\n";
}

int main() {
    std::cout << "--- Call 1 ---\n";
    staticArrayDemo();
    automaticArrayDemo();

    std::cout << "--- Call 2 ---\n";
    staticArrayDemo();
    automaticArrayDemo();

    return 0;
}
